// MCP tool descriptors. Each pairs a schema with a tool name and description
// so that LLM clients can discover and invoke the underlying RPCs.
var (
	Resources_CreateResourceTool   = newTool("resources-create_resource_v1", `Creates a resource. POST /v1/resources body: the resource itself Server-assigned fields on the request body are ignored: `+"`"+`name`+"`"+`, `+"`"+`uid`+"`"+`, `+"`"+`etag`+"`"+` and the timestamps are set by the server regardless of what is sent. Supply `+"`"+`resource_id`+"`"+` to choose the final path segment; leave it empty and the server generates one. Not idempotent. Retrying after a timeout may create a second resource; supply `+"`"+`resource_id`+"`"+` if the caller needs retry safety. ALREADY_EXISTS     that resource_id is taken INVALID_ARGUMENT   a field violates its buf.validate constraint PERMISSION_DENIED  caller may not create here`, Resources_CreateResourceSchemaJSON, Resources_CreateResourceOutputSchemaJSON, nil, "", nil)
	Resources_DeleteResourceTool   = newTool("resources-delete_resource_v1", `Deletes a resource. DELETE /v1/{name=resources/*} Soft delete: the resource is marked deleted, disappears from List unless `+"`"+`show_deleted`+"`"+` is set, and is purged at `+"`"+`expire_time`+"`"+`. Recover it with Undelete before then. Bookings already on its calendar are untouched -- retiring a bay does not cancel what is parked on it. Idempotent in effect but not in reporting: a second delete returns NOT_FOUND rather than succeeding silently. NOT_FOUND          no such resource ABORTED            etag does not match PERMISSION_DENIED  caller may not delete it`, Resources_DeleteResourceSchemaJSON, Resources_DeleteResourceOutputSchemaJSON, nil, "", nil)
	Resources_GetResourceTool      = newTool("resources-get_resource_v1", `Retrieves one resource. GET /v1/{name=resources/*} Safe and idempotent. Returns the resource as stored; no field is computed per-caller. Read the `+"`"+`etag`+"`"+` here and pass it back on update or delete to make the write conditional. NOT_FOUND          no such resource, or it is soft-deleted and `+"`"+`show_deleted`+"`"+` was not set INVALID_ARGUMENT   name does not match resources/* PERMISSION_DENIED  caller may not read it`, Resources_GetResourceSchemaJSON, Resources_GetResourceOutputSchemaJSON, nil, "", nil)
	Resources_ListResourcesTool    = newTool("resources-list_resources_v1", `Lists resources. GET /v1/resources Paginated per AIP-158: pass `+"`"+`page_size`+"`"+` (defaults to 50, capped at 1000) and the `+"`"+`next_page_token`+"`"+` from the previous response. An empty `+"`"+`next_page_token`+"`"+` means the last page. Page tokens are opaque and may expire; do not construct or store them. Filtering uses the AIP-160 expression language over the resource's own fields -- `+"`"+`resource_types:"room"`+"`"+` narrows by kind, and `+"`"+`calendar="calendars/bay-14"`+"`"+` finds what one calendar schedules, since the collection is flat rather than nested. Results carry no guaranteed order. INVALID_ARGUMENT   malformed filter, or page_size out of range PERMISSION_DENIED  caller may not list this collection`, Resources_ListResourcesSchemaJSON, Resources_ListResourcesOutputSchemaJSON, nil, "", nil)
	Resources_UndeleteResourceTool = newTool("resources-undelete_resource_v1", `Restores a soft-deleted resource. POST /v1/{name=resources/*}:undelete Valid only before `+"`"+`expire_time`+"`"+`; after that the resource is gone and this returns NOT_FOUND. Clears `+"`"+`delete_time`+"`"+` and `+"`"+`expire_time`+"`"+` and returns the resource as it was. NOT_FOUND          no such resource, or already purged ALREADY_EXISTS     the resource is not deleted PERMISSION_DENIED  caller may not restore it`, Resources_UndeleteResourceSchemaJSON, Resources_UndeleteResourceOutputSchemaJSON, nil, "", nil)
	Resources_UpdateResourceTool   = newTool("resources-update_resource_v1", `Updates a resource. PATCH /v1/{resource.name=resources/*} body: the resource itself A partial update: only fields named in `+"`"+`update_mask`+"`"+` are written. An empty mask writes every mutable field, which will clear anything the caller left unset -- pass a mask unless that is the intent. OUTPUT_ONLY and IMMUTABLE fields are rejected rather than silently dropped. Idempotent. Pass the `+"`"+`etag`+"`"+` read from Get to make the write conditional. NOT_FOUND          no such resource ABORTED            etag does not match the stored resource INVALID_ARGUMENT   mask names an unknown or immutable field PERMISSION_DENIED  caller may not modify it`, Resources_UpdateResourceSchemaJSON, Resources_UpdateResourceOutputSchemaJSON, nil, "", nil)
)

